package com.company.crm.common.storage;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where uploaded document bytes live (FR-1.5). Keys are generated by the caller and never contain
 * user input. Today: local disk ({@link LocalDocumentStorage}); a cloud implementation (ARC-7)
 * can replace it without touching callers.
 */
public interface DocumentStorage {

    void store(String key, InputStream content) throws IOException;

    InputStream open(String key) throws IOException;

    /** Removes the object; a missing object is not an error. */
    void delete(String key) throws IOException;
}
